const skills: TestSkill[] = ["reading", "grammar", "vocabulary", "writing", "listening", "pronunciation"];
const skillNames = { en: ["Critical reading", "Grammar in argument", "Precise vocabulary", "Source synthesis", "Listening and inference", "Defending a position"], ko: ["비판적 읽기", "논증의 문법", "정밀한 어휘", "자료 종합 쓰기", "듣기와 추론", "입장 설명과 반론"] };
const focuses: Record<TestLanguage, Record<TestSkill, string[]>> = {
  en: {
    reading: ["Scope · representativeness · warranted conclusions", "Correlation vs causation · selection · competing explanations", "Implicit consequences · evidence transfer · safeguards"],
    grammar: ["Inverted past conditions · concession", "Negative inversion · modal perfect hedging", "Degree concession · conditional permission"],
    vocabulary: ["Blanket policy · warrant caution", "Isolate an effect · subject to bias", "Disproportionate burdens · grounds for inquiry"],
    writing: ["Shared ground · synthesis · proportionate trade-offs", "Qualified attribution · ethical evaluation", "Conditional proposals · procedural transparency"],
    listening: ["Missing perspectives · speaker qualification", "Alternative causes · support vs expansion", "Implied burdens · technical vs procedural disclosure"],
    pronunciation: ["Contrastive stress · clause grouping", "Degrees of certainty · respectful clarification", "Responsive counterargument · precise scope"],
  },
  ko: {
    reading: ["범위 · 대표성 · 근거 있는 결론", "상관과 인과 · 참여 선택 · 대안 설명", "간접적 영향 · 근거 적용 · 보호 절차"],
    grammar: ["-다고 해서 · -기보다는", "-을 수 있으나 · -았/었더라면", "-다고 하더라도 · 전제하에"],
    vocabulary: ["접근성 · 일반화와 검증", "기여와 요인 · 상관관계와 인과관계", "부담의 집중 · 잠정적 신호와 결정적 증거"],
    writing: ["공통점 종합 · 근거 한계 · 비용 반론", "신중한 원인 해석 · 지원과 평가", "조건부 제안 · 절차의 투명성"],
    listening: ["빠진 관점 · 화자의 확신 정도", "대안 원인 · 지원과 확대의 구분", "암시된 부담 · 공개 범위의 구분"],
    pronunciation: ["의미 단위 · 장점과 한계의 대비", "가능성과 확정 · 정중한 확인", "추가 반론 응답 · 제안 범위 설명"],
  },
};

function question(seed: QuestionSeed, id: string, skill: string, text: string | undefined, offset: number): TestQuestion {
  const choices = [...seed.choices.slice(offset), ...seed.choices.slice(0, offset)];
  return { id, skill, prompt: seed.prompt, passage: text, options: choices.map(([answer]) => answer), correctIndex: (4 - offset) % 4,
    optionFeedback: choices.map(([, feedback]) => feedback), explanation: seed.choices[0][1], improvement: seed.lesson,
    lesson: seed.lesson, example: seed.example, transfer: seed.transfer };
}

function makeAdvancedTrack(language: TestLanguage): TestTrack {
  const ko = language === "ko";
  const scenarios = ko ? korean : english;
  const stages = skills.flatMap((skill, skillIndex) => scenarios.map((scenario, index): TestStage => {
    const id = `${language}-c1-${skill}-${String(index + 1).padStart(2, "0")}`;
    const skillName = skillNames[language][skillIndex];
    const primary = skill === "reading" || skill === "listening" ? scenario.reading : scenario[skill];
    const seeds = skill === "reading" || skill === "listening" ? primary : [...primary, ...scenario.reading.slice(0, 2)];
    const challenges = skill === "writing" || skill === "pronunciation" ? [...scenario.grammar.slice(0, 1), ...scenario.vocabulary.slice(1)] : scenario.writing;
    const context = `${scenario.text}\n\n${ko ? "검토할 반론" : "Counterargument to address"}: ${scenario.counterargument}`;
    const isWriting = skill === "writing";
    const mode = skill === "listening" ? "listening" : skill === "pronunciation" ? "speaking" : "writing";
    const task = ko
      ? isWriting ? "500~700자: 두 자료의 관계를 종합하고, 근거의 한계를 밝힌 뒤 반론에 답하는 조건부 제안을 쓰세요."
        : mode === "speaking" ? `${90 + index * 15}초: 자료를 바탕으로 입장, 근거, 한계, 반론에 대한 응답을 말하세요. 이어서 제안을 바꿀 조건을 설명하세요.`
        : mode === "listening" ? "먼저 대본을 보지 않고 듣고, 두 입장의 공통점·차이점과 확신의 정도를 메모하세요. 다시 듣고 추론을 뒷받침하는 근거를 확인하세요."
        : `140~220자: ${skill === "grammar" ? "이번 문법 두 가지로" : skill === "vocabulary" ? "핵심 표현 두 가지를 정확히 사용하여" : "글의 단서 두 곳을 근거로"} 주장과 한계를 연결하는 짧은 답을 쓰세요.`
      : isWriting ? "Write 220–260 words synthesising the two sources. Qualify the evidence, address the counterargument, and recommend a conditional next step."
        : mode === "speaking" ? `Speak for ${90 + index * 15} seconds: defend a position with evidence, acknowledge a limitation, answer the counterargument, then explain what would change your recommendation.`
        : mode === "listening" ? "Listen before opening the transcript. Note the speakers' shared aim, disagreement and degree of certainty. Listen again to check the evidence for one inference."
        : `Write 60–100 words linking a claim to its limitation, ${skill === "grammar" ? "using both grammar patterns from this activity" : skill === "vocabulary" ? "using two precise expressions from this activity" : "citing two clues from the text"}.`;
    return { id, order: index + 1, skill, icon: ko ? "심" : "C1", title: `${skillName} · ${scenario.title}`,
      description: ko ? `심화 ${index + 1}단계: ${scenario.conclusion}` : `Advanced step ${index + 1}: ${scenario.conclusion}`,
      focus: focuses[language][skill][index],
      estimatedMinutes: isWriting ? 16 + index * 2 : 10 + index * 2, passScore: 80,
      productionTask: { mode, prompt: task, context: mode === "listening" ? (ko ? "가상의 대학 정책 토론 · 원본 연습 대본" : "Fictional campus policy discussion · original practice script") : context,
        instructions: ko ? "한 번에 한 활동만 하세요. 관련 있는 이전 학습 하나를 적용하고, 다시 검토할 때 한 가지 개선에 집중하세요." : "Do one activity at a time. Transfer one relevant earlier technique; focus on one improvement when revising.",
        checklist: [ko ? "주장과 근거를 구별하고 자료를 왜곡하지 않았습니다." : "I distinguished the claim from the evidence without misrepresenting the sources.",
          ko ? "반론이나 한계를 인정하고 조건부 제안을 제시했습니다." : "I acknowledged a counterargument or limitation and made a conditional recommendation.",
          ko ? "표현의 정확성과 자연스러운 연결을 검토했습니다." : "I reviewed precise expression and natural connections."],
        ...(mode === "writing" ? { minimumCharacters: ko ? (isWriting ? 500 : 140) : 100, ...(ko ? { maximumCharacters: isWriting ? 700 : 220 } : { minimumWords: isWriting ? 220 : 60, maximumWords: isWriting ? 260 : 100 }) } : {}),
        ...(mode === "speaking" ? { targetSeconds: 90 + index * 15 } : {}),
        ...(mode === "listening" ? { listeningScript: scenario.text.replace(/\n+/gu, " ") } : {}),
        retakeInstruction: ko ? "틀린 추론이나 표현 한 가지를 고치고 다른 근거로 같은 제안을 다시 설명하세요." : "Correct one inference or expression, then defend the same recommendation using a different piece of evidence." },
      questions: seeds.map((seed, i) => question(seed, `${id}-q${i + 1}`, skillName, mode === "listening" ? undefined : scenario.text, (index + skillIndex + i) % 4)),
      challengeQuestions: challenges.map((seed, i) => question(seed, `${id}-challenge${i + 1}`, skillName, mode === "listening" ? undefined : scenario.text, (index + skillIndex + i + 2) % 4)),
    };
  }));
  // A single brief recall transfers the last foundation skill into C1, then the preceding advanced step.
  for (const stage of stages) {
    const previous = stage.order === 1 ? practiceTestTracks[language].stages.filter((candidate) => candidate.skill === stage.skill).at(-1)!
      : stages.find((candidate) => candidate.skill === stage.skill && candidate.order === stage.order - 1)!;
    const source = previous.questions[0];
    const application = ko ? "이전 활동의 표현이나 분석 방법 하나를 이번 자료에 맞게 적용하세요. 관련 없는 내용은 억지로 넣지 마세요." : "Apply one expression or analytical technique from the previous activity to this scenario; do not force an unrelated topic into your answer.";
    stage.learningBridge = { previousStageId: previous.id, previousTitle: previous.title, recall: previous.focus, application, example: source.example };
    stage.questions.push({ ...source, id: `${stage.id}-recall`, skill: ko ? "짧은 복습" : "Brief recall", prompt: ko ? `이전 방법을 떠올려 보세요. ${source.prompt}` : `Recall the previous technique: ${source.prompt}`, transfer: application });
    stage.productionTask.checklist[2] = application;
  }
  return { language, shortLabel: ko ? "한" : "EN", label: ko ? "한국어 심화 · 내부 C1 도전" : "English C1",
    target: ko ? "심화 연습 · C1은 내부 난도이며 TOPIK 등급과 동등하지 않습니다" : "C1 practice · not a certified CEFR level",
    sourceLabel: ko ? "NIIED · official TOPIK framework (no C1 equivalence)" : "Council of Europe · CEFR descriptors (practice reference)",
    sourceUrl: ko ? "https://niied.go.kr/web/niied/contents/niied_topik" : "https://www.coe.int/en/web/common-european-framework-reference-languages/cefr-descriptors", stages };
}

export const advancedPracticeTracks: Record<TestLanguage, TestTrack> = { en: makeAdvancedTrack("en"), ko: makeAdvancedTrack("ko") };
